<?php
declare(strict_types=1);

namespace MiniERP\Infrastructure\Database;

use ReflectionProperty;
use RuntimeException;
use Throwable;
use wpdb;

/** Cash, payment, expense, and manual-reconciliation ledgers. */
final class CashSchema
{
    public function __construct(private readonly wpdb $db) {}

    public function migrate(): void
    {
        $prefix=$this->db->prefix;if(!is_string($prefix)||strlen($prefix)>32||!preg_match('/\A[A-Za-z0-9_]+\z/D',$prefix))throw new RuntimeException('The WordPress database prefix is not supported.');
        try{$connection=(new ReflectionProperty($this->db,'dbh'))->getValue($this->db);}catch(Throwable){throw new RuntimeException('The WordPress database connection is unavailable.');}
        if(!$connection instanceof \mysqli)throw new RuntimeException('Cash schema migration requires a live MySQL connection.');
        $lock='mini-erp-cash:'.substr(hash('sha256',$this->db->dbname.':'.$prefix),0,40);$escaped=$connection->real_escape_string($lock);
        if((string)$this->scalar($connection,"SELECT GET_LOCK('{$escaped}',5)")!=='1')throw new RuntimeException('Could not acquire the bounded cash schema lock.');
        $failure=null;try{foreach($this->statements($prefix) as $suffix=>$sql){if($connection->query($sql)===false)throw new RuntimeException('A required cash schema operation failed.');$this->assertTable($connection,$prefix.$suffix,$suffix);}}catch(Throwable $e){$failure=$e;}
        $release=null;try{if((string)$this->scalar($connection,"SELECT RELEASE_LOCK('{$escaped}')")!=='1')$release=new RuntimeException('The cash schema lock could not be released cleanly.');}catch(Throwable $e){$release=$e;}
        if($failure!==null)throw $failure;if($release!==null)throw new RuntimeException('The cash schema lock could not be released cleanly.',0,$release);
    }

    /** @return array<string,string> */
    private function statements(string $p):array
    {
        $h=substr(hash('sha256',$this->db->dbname.':'.$p),0,10);$engine=' ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci';
        $accounts='`'.$p.'erp_cash_accounts`';$invoices='`'.$p.'erp_invoices`';$payments='`'.$p.'erp_payments`';$movements='`'.$p.'erp_cash_movements`';$expenses='`'.$p.'erp_expenses`';$recs='`'.$p.'erp_reconciliations`';$recItems='`'.$p.'erp_reconciliation_items`';
        return [
            'erp_cash_accounts'=>"CREATE TABLE IF NOT EXISTS {$accounts} (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,account_code VARCHAR(64) NOT NULL,name VARCHAR(191) NOT NULL,type VARCHAR(8) NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'VND',opening_balance_vnd BIGINT NOT NULL DEFAULT 0,status VARCHAR(16) NOT NULL,created_by BIGINT UNSIGNED NOT NULL,activated_by BIGINT UNSIGNED NULL,activated_at DATETIME(6) NULL,created_at DATETIME(6) NOT NULL,UNIQUE KEY account_code(account_code),KEY status_created(status,created_at),CONSTRAINT ck_{$h}_ca_type CHECK(type IN ('CASH','BANK')),CONSTRAINT ck_{$h}_ca_currency CHECK(currency='VND'),CONSTRAINT ck_{$h}_ca_status CHECK(status IN ('DRAFT','ACTIVE','INACTIVE')),CONSTRAINT ck_{$h}_ca_balance CHECK(opening_balance_vnd>=0)){$engine}",
            'erp_payments'=>"CREATE TABLE IF NOT EXISTS {$payments} (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,payment_no VARCHAR(32) NOT NULL,invoice_id BIGINT UNSIGNED NOT NULL,direction VARCHAR(3) NOT NULL,amount_vnd BIGINT NOT NULL,cash_account_id BIGINT UNSIGNED NOT NULL,method VARCHAR(24) NOT NULL,external_reference VARCHAR(128) NOT NULL DEFAULT '',paid_at DATETIME(6) NOT NULL,posted_at DATETIME(6) NOT NULL,status VARCHAR(24) NOT NULL,created_by BIGINT UNSIGNED NOT NULL,void_reason VARCHAR(1000) NOT NULL DEFAULT '',void_requested_by BIGINT UNSIGNED NULL,void_approved_by BIGINT UNSIGNED NULL,void_approved_at DATETIME(6) NULL,void_rejected_by BIGINT UNSIGNED NULL,void_rejected_at DATETIME(6) NULL,void_rejection_reason VARCHAR(1000) NOT NULL DEFAULT '',void_applied_by BIGINT UNSIGNED NULL,request_key CHAR(36) NOT NULL,UNIQUE KEY payment_no(payment_no),UNIQUE KEY request_key(request_key),KEY invoice_status(invoice_id,status,posted_at),KEY account_posted(cash_account_id,posted_at),CONSTRAINT fk_{$h}_pay_invoice FOREIGN KEY(invoice_id) REFERENCES {$invoices}(id) ON DELETE RESTRICT,CONSTRAINT fk_{$h}_pay_account FOREIGN KEY(cash_account_id) REFERENCES {$accounts}(id) ON DELETE RESTRICT,CONSTRAINT ck_{$h}_pay_direction CHECK(direction IN ('IN','OUT')),CONSTRAINT ck_{$h}_pay_status CHECK(status IN ('POSTED','VOID_PENDING','VOID_APPROVED','VOID')),CONSTRAINT ck_{$h}_pay_amount CHECK(amount_vnd>0)){$engine}",
            'erp_cash_movements'=>"CREATE TABLE IF NOT EXISTS {$movements} (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,cash_account_id BIGINT UNSIGNED NOT NULL,event_key VARCHAR(128) NOT NULL,source_type VARCHAR(24) NOT NULL,source_id BIGINT UNSIGNED NOT NULL,direction VARCHAR(3) NOT NULL,amount_vnd BIGINT NOT NULL,occurred_at DATETIME(6) NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,external_reference VARCHAR(128) NOT NULL DEFAULT '',created_at DATETIME(6) NOT NULL,UNIQUE KEY event_key(event_key),KEY account_occurred(cash_account_id,occurred_at),KEY source(source_type,source_id),CONSTRAINT fk_{$h}_cm_account FOREIGN KEY(cash_account_id) REFERENCES {$accounts}(id) ON DELETE RESTRICT,CONSTRAINT ck_{$h}_cm_direction CHECK(direction IN ('IN','OUT')),CONSTRAINT ck_{$h}_cm_amount CHECK(amount_vnd>0)){$engine}",
            'erp_expenses'=>"CREATE TABLE IF NOT EXISTS {$expenses} (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,expense_no VARCHAR(32) NOT NULL,category VARCHAR(64) NOT NULL,description VARCHAR(1000) NOT NULL,amount_vnd BIGINT NOT NULL,occurred_at DATETIME(6) NOT NULL,recorded_by BIGINT UNSIGNED NOT NULL,cash_account_id BIGINT UNSIGNED NOT NULL,status VARCHAR(16) NOT NULL,request_key CHAR(36) NOT NULL,UNIQUE KEY expense_no(expense_no),UNIQUE KEY request_key(request_key),KEY account_occurred(cash_account_id,occurred_at),CONSTRAINT fk_{$h}_ex_account FOREIGN KEY(cash_account_id) REFERENCES {$accounts}(id) ON DELETE RESTRICT,CONSTRAINT ck_{$h}_ex_status CHECK(status IN ('POSTED')),CONSTRAINT ck_{$h}_ex_amount CHECK(amount_vnd>0)){$engine}",
            'erp_reconciliations'=>"CREATE TABLE IF NOT EXISTS {$recs} (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,rec_no VARCHAR(32) NOT NULL,cash_account_id BIGINT UNSIGNED NOT NULL,period_from DATE NOT NULL,period_to DATE NOT NULL,statement_opening_vnd BIGINT NOT NULL,statement_closing_vnd BIGINT NOT NULL,status VARCHAR(16) NOT NULL,created_by BIGINT UNSIGNED NOT NULL,closed_by BIGINT UNSIGNED NULL,closed_at DATETIME(6) NULL,note VARCHAR(1000) NOT NULL DEFAULT '',UNIQUE KEY rec_no(rec_no),KEY account_period(cash_account_id,period_from,period_to),CONSTRAINT fk_{$h}_rec_account FOREIGN KEY(cash_account_id) REFERENCES {$accounts}(id) ON DELETE RESTRICT,CONSTRAINT ck_{$h}_rec_status CHECK(status IN ('DRAFT','CLOSED')),CONSTRAINT ck_{$h}_rec_period CHECK(period_to>=period_from)){$engine}",
            'erp_reconciliation_items'=>"CREATE TABLE IF NOT EXISTS {$recItems} (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,reconciliation_id BIGINT UNSIGNED NOT NULL,cash_movement_id BIGINT UNSIGNED NOT NULL,external_reference VARCHAR(128) NULL,external_amount_vnd BIGINT NOT NULL,matched_by BIGINT UNSIGNED NOT NULL,matched_at DATETIME(6) NOT NULL,UNIQUE KEY movement_once(cash_movement_id),UNIQUE KEY batch_reference(reconciliation_id,external_reference),CONSTRAINT fk_{$h}_ri_rec FOREIGN KEY(reconciliation_id) REFERENCES {$recs}(id) ON DELETE RESTRICT,CONSTRAINT fk_{$h}_ri_movement FOREIGN KEY(cash_movement_id) REFERENCES {$movements}(id) ON DELETE RESTRICT,CONSTRAINT ck_{$h}_ri_amount CHECK(external_amount_vnd>0)){$engine}",
        ];
    }

    private function assertTable(\mysqli $connection,string $table,string $suffix):void
    {
        $db=$connection->real_escape_string($this->db->dbname);$name=$connection->real_escape_string($table);$r=$connection->query("SELECT ENGINE,TABLE_COLLATION FROM information_schema.TABLES WHERE TABLE_SCHEMA='{$db}' AND TABLE_NAME='{$name}'");$row=$r instanceof \mysqli_result?$r->fetch_assoc():null;if($r instanceof \mysqli_result)$r->free();
        if(!is_array($row)||strtoupper((string)$row['ENGINE'])!=='INNODB'||!str_starts_with(strtolower((string)$row['TABLE_COLLATION']),'utf8mb4_'))throw new RuntimeException('An existing cash table is incompatible; it was left unchanged.');
        $r=$connection->query("SELECT COLUMN_NAME,COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='{$db}' AND TABLE_NAME='{$name}'");if(!$r instanceof \mysqli_result)throw new RuntimeException('Could not inspect cash schema metadata.');$columns=[];while(($c=$r->fetch_assoc())!==null)$columns[(string)$c['COLUMN_NAME']]=strtolower((string)$c['COLUMN_TYPE']);$r->free();
        $required=match($suffix){'erp_cash_accounts'=>['id'=>'bigint unsigned','account_code'=>'varchar(64)','name'=>'varchar(191)','type'=>'varchar(8)','currency'=>'char(3)','opening_balance_vnd'=>'bigint','status'=>'varchar(16)','created_by'=>'bigint unsigned','activated_by'=>'bigint unsigned','activated_at'=>'datetime(6)','created_at'=>'datetime(6)'],'erp_payments'=>['id'=>'bigint unsigned','payment_no'=>'varchar(32)','invoice_id'=>'bigint unsigned','direction'=>'varchar(3)','amount_vnd'=>'bigint','cash_account_id'=>'bigint unsigned','method'=>'varchar(24)','external_reference'=>'varchar(128)','paid_at'=>'datetime(6)','posted_at'=>'datetime(6)','status'=>'varchar(24)','created_by'=>'bigint unsigned','request_key'=>'char(36)'],'erp_cash_movements'=>['id'=>'bigint unsigned','cash_account_id'=>'bigint unsigned','event_key'=>'varchar(128)','source_type'=>'varchar(24)','source_id'=>'bigint unsigned','direction'=>'varchar(3)','amount_vnd'=>'bigint','occurred_at'=>'datetime(6)','actor_id'=>'bigint unsigned','created_at'=>'datetime(6)'],'erp_expenses'=>['id'=>'bigint unsigned','expense_no'=>'varchar(32)','category'=>'varchar(64)','description'=>'varchar(1000)','amount_vnd'=>'bigint','occurred_at'=>'datetime(6)','recorded_by'=>'bigint unsigned','cash_account_id'=>'bigint unsigned','status'=>'varchar(16)','request_key'=>'char(36)'],'erp_reconciliations'=>['id'=>'bigint unsigned','rec_no'=>'varchar(32)','cash_account_id'=>'bigint unsigned','period_from'=>'date','period_to'=>'date','statement_opening_vnd'=>'bigint','statement_closing_vnd'=>'bigint','status'=>'varchar(16)','created_by'=>'bigint unsigned','closed_by'=>'bigint unsigned','closed_at'=>'datetime(6)','note'=>'varchar(1000)'],'erp_reconciliation_items'=>['id'=>'bigint unsigned','reconciliation_id'=>'bigint unsigned','cash_movement_id'=>'bigint unsigned','external_reference'=>'varchar(128)','external_amount_vnd'=>'bigint','matched_by'=>'bigint unsigned','matched_at'=>'datetime(6)'],default=>[]};
        foreach($required as $column=>$type)if(($columns[$column]??null)!==$type)throw new RuntimeException('An existing cash table is incompatible; it was left unchanged.');
        $r=$connection->query("SELECT INDEX_NAME,NON_UNIQUE,SEQ_IN_INDEX,COLUMN_NAME FROM information_schema.STATISTICS WHERE TABLE_SCHEMA='{$db}' AND TABLE_NAME='{$name}' ORDER BY INDEX_NAME,SEQ_IN_INDEX");if(!$r instanceof \mysqli_result)throw new RuntimeException('Could not inspect cash index metadata.');$indexes=[];while(($index=$r->fetch_assoc())!==null){$key=(string)$index['INDEX_NAME'];$indexes[$key]['columns'][]=(string)$index['COLUMN_NAME'];$indexes[$key]['unique']=(int)$index['NON_UNIQUE']===0;}$r->free();
        $unique=match($suffix){'erp_cash_accounts'=>['account_code'=>['account_code']],'erp_payments'=>['payment_no'=>['payment_no'],'request_key'=>['request_key']],'erp_cash_movements'=>['event_key'=>['event_key']],'erp_expenses'=>['expense_no'=>['expense_no'],'request_key'=>['request_key']],'erp_reconciliations'=>['rec_no'=>['rec_no']],'erp_reconciliation_items'=>['movement_once'=>['cash_movement_id'],'batch_reference'=>['reconciliation_id','external_reference']],default=>[]};
        foreach($unique as $key=>$indexColumns)if(($indexes[$key]['columns']??null)!==$indexColumns||($indexes[$key]['unique']??false)!==true)throw new RuntimeException('An existing cash table is missing a required unique index; it was left unchanged.');
    }

    private function scalar(\mysqli $connection,string $sql):mixed{$r=$connection->query($sql);if(!$r instanceof \mysqli_result)throw new RuntimeException('A required cash schema operation failed.');$row=$r->fetch_row();$r->free();return $row[0]??null;}
}
